  const web3 = new Web3(new Web3.providers.HttpProvider('https://mainnet.infura.io/v3/YOUR_PROJECT_ID'));
  return await web3.eth.getBlockchainData();
}

// Funktion zur Récupération der Gerätendaten
async function getGerätedaten() {
  const geräteAPI = new GeräteAPI('YOUR_GERÄTE_API_KEY');
  return await geräteAPI.getPatientDaten();
}
